def main():
 rows=read('branch_matrix.json');remote=[r for r in rows if r['kind']=='remote'];allremote=[r['ref'] for r in remote];blobrefs=defaultdict(set);trees={}
 for r in remote:
  ts=tree(r['ref']);trees[r['sha']]=ts
  csvout(r['tree_index'],[{'path':x['path'],'mode':'','type':'blob','blob':x['blob'],'git_blob_bytes':x['bytes']} for x in ts])
  for t in ts:blobrefs[t['blob']].add(r['name'])
 for r in rows:
  n=r['name']
  if n.startswith('yios-test/'):
   notes=('Isolated non-production coordination smoke history','Test checkpoints/claim-state objects for TEST0000001/2; both claim tips RELEASED.','Not a production writer lease, accepted Finance research or a branch to reuse for real videos.','state.json; research/tasks/')
  else:notes=NOTES.get(n,NOTES['research/finance-economics-intelligence'] if n.startswith('claude/finance-audits') else None)
  assert notes,n
  r.update(dict(zip(['purpose','completed_work','unfinished_or_limitations','authority_paths'],notes)))
  r['latest_commit_subject']=git('show','-s','--format=%s',r['ref']);r['head_commit_changed_paths']=git('diff-tree','--root','--no-commit-id','--name-status','-r',r['ref']).splitlines()
  r['exclusive_commits_vs_other_remote_branches']=int(git('rev-list','--count',r['ref'],'--not',*[v for v in allremote if v!=r['ref'] and not (r['kind']=='local' and v==r['upstream'])]) or '0')
  if not r['merge_base']:
   r['history_relationship']='UNRELATED_HISTORY_NO_MERGE_BASE';r['merge_base']=None
   changes=[]
   for ln in git('diff','--numstat','4b825dc642cb6eb9a060e54bf8d69288fbee4904',r['ref']).splitlines():
    v=ln.split('\t',2)
    if len(v)==3:changes.append(dict(zip(['additions','deletions','path'],v)))
   csvout('branches/diffs/'+r['sha'][:12]+'.csv',changes);r['changed_files_since_merge_base']=None;r['root_tree_files_when_no_common_ancestor']=len(changes)
  else:r['history_relationship']='COMMON_ANCESTOR'
  ts=trees.get(r['sha']) or tree(r['ref']);exclusive=[t for t in ts if len(blobrefs[t['blob']])==1 and n in blobrefs[t['blob']]]
  r['exclusive_tip_blobs_vs_other_remote_branches']=len(exclusive);r['unpublished_local_commits_count']=len(r['local_only_commits'])
  r['latest_validated_checkpoint']='Fresh local validation only where listed in validation_results.json; published per-path declarations in published_validation_declarations.json are historical, not rerun.'
  csvout('branches/exclusive/'+r['sha'][:12]+'.csv',exclusive,['path','blob','bytes'])
 write('branch_matrix.json',rows);csvout('branch_matrix.csv',rows)
 lines=['# Complete branch audit — 2026-11-02','', '46 authenticated remote branches and24 local branches, including the local-only-named Claude branch (its commit is published on its configured upstream). Full SHAs, commit lists, diffs and file trees are in branch_matrix.csv/JSON and branches/. Counts since the default merge base include inherited work, not only work authored on the named branch. Exact-content reuse is not independent evidence.','']
 for r in remote:
  row=next(x for x in rows if x['ref']==r['ref']);pr='; '.join(f"#{p['number']} {p['state']} {'DRAFT' if p['draft'] else ''} {'MERGED' if p['merged'] else 'NOT_MERGED'}" for p in row['prs']) or 'No associated PR returned by full repository PR inventory.'
  lines += ['## '+row['name'],'',f"HEAD `{row['sha']}`. {row['ahead_default']} ahead / {row['behind_default']} behind default. {row['integration_assessment']}. Exclusive commits against other remote branches: {row['exclusive_commits_vs_other_remote_branches']}. Files changed since default merge base: {row['changed_files_since_merge_base']}; root tree count applies where no common ancestor. Exclusive tip blobs: {row['exclusive_tip_blobs_vs_other_remote_branches']}.",'',row['purpose']+'. '+row['completed_work'],'',row['unfinished_or_limitations'],'',f"Authority: `{row['authority_paths']}`. Latest commit: {row['latest_commit_subject']}. PR: {pr}",'',f"Worktree: {next((x['worktree'] for x in rows if x['name']==row['name'] and x['worktree']), 'None')}. Reuse: {row['reuse_assessment']}. Validation: {row['latest_validated_checkpoint']}",'']
 write('BRANCH_AUDIT.md','\n'.join(lines));print('Annotated',len(rows),'refs; complete remote chapters',len(remote))
